{"command":"python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
out = '/root/output/result.xlsx'
wb = load_workbook(out, data_only=False)
ws = wb['Task']
print('Sheets:', wb.sheetnames)

checks = ['H12','L17','H19','L24','H26','L31']
print('\nLookup formula checks:')
for cell in checks:
    print(cell, ws[cell].value)

print('\nNet reliability gap checks:')
for cell in ['H35','L40']:
    print(cell, ws[cell].value)

print('\nSummary H42:H47 checks:')
for r in range(42,48):
    print(f'H{r}', ws[f'H{r}'].value)

print('\nWeighted mean H50:L50 checks:')
for c in range(8,13):
    cell = f'{get_column_letter(c)}50'
    print(cell, ws[cell].value)

# Programmatic validation of required populated formula cells and no #NAME? text.
errors = []
for rangestr in ['H12:L17', 'H19:L24', 'H26:L31', 'H35:L40', 'H42:L47', 'H50:L50']:
    for row in ws[rangestr]:
        for cell in row:
            val = cell.value
            if val is None:
                errors.append(f'{cell.coordinate} is None')
            elif not isinstance(val, str) or not val.startswith('='):
                errors.append(f'{cell.coordinate} is not a formula string: {val!r}')
            elif '#NAME?' in val:
                errors.append(f'{cell.coordinate} contains #NAME?: {val!r}')
for cell in ['H46','H47']:
    val = ws[cell].value
    if 'PERCENTILE(' not in val or 'PERCENTILE.' in val:
        errors.append(f'{cell} percentile formula is wrong: {val!r}')
if wb.sheetnames != ['Task', 'Data']:
    errors.append(f'Unexpected sheets: {wb.sheetnames}')

if errors:
    print('\nVALIDATION FAILED:')
    for err in errors:
        print(' -', err)
    raise SystemExit(1)
print('\nVALIDATION PASSED')
